contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum) public payable {
        (uint beforeAccUnlockTime, uint beforeAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;
        (uint afterAccUnlockTime, uint afterAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        assert(
            (reverted && afterMinSum == beforeMinSum && afterContractBalance == beforeContractBalance && afterAccBalance == beforeAccBalance && afterAccUnlockTime == beforeAccUnlockTime)
            ||
            (!reverted && afterMinSum == newMinSum && afterContractBalance == beforeContractBalance && afterAccBalance == beforeAccBalance && afterAccUnlockTime == beforeAccUnlockTime)
        );
    }

    receive() external payable {}
}

